async function run() {
  console.log('Importing ' + articles.length + ' articles...\n');
  let inserted = 0, skipped = 0, errors = 0;

  for (const a of articles) {
    try {
      const [existing] = await db.query(
        'SELECT id FROM blog_articles WHERE slug = ? LIMIT 1', [a.slug]
      );
      if (existing.length) {
        console.log('⏭  Already exists: ' + a.slug);
        skipped++;
        continue;
      }

      await db.query(
        `INSERT INTO blog_articles
         (title, slug, content, excerpt, category, tags, author, reading_time,
          status, meta_title, meta_description, published_at)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,NOW())`,
        [a.title, a.slug, a.content, a.excerpt, a.category,
         a.tags, a.author || 'JobOrbit Editorial', a.reading_time || 6,
         'published',
         a.meta_title || a.title,
         a.meta_description || a.excerpt]
      );
      console.log('✅ Imported: ' + a.title);
      inserted++;
    } catch(e) {
      console.log('❌ Error on ' + a.slug + ': ' + e.message);
      errors++;
    }
  }

  console.log('\n📊 Done: ' + inserted + ' imported, ' + skipped + ' skipped, ' + errors + ' errors');
  process.exit(0);
}

run().catch(e => { console.error(e); process.exit(1); });
